import{_ as e,o,c as a,a2 as r}from"./chunks/framework.mRCPFc5l.js";const d=JSON.parse('{"title":"ai-agent-book","description":"","frontmatter":{"title":"ai-agent-book","date":"2026-08-15T00:00:00.000Z","type":"tool","source":"bilibili/BV1EcGw6eE3o（《深入理解AI Agent设计原理与工程实践》书评）","tags":["agent","harness","教材"],"verified":true,"rating":5,"url":"https://github.com/bojieli/ai-agent-book","summary":"开源可运行的 AI Agent 工程教材：Agent=LLM+上下文+工具+约束+验证+纠正，把\\"模型趋同→竞争在harness\\"落成诊断公式","tools":["ai-agent-book"]},"headers":[],"relativePath":"tools/ai-agent-book.md","filePath":"tools/ai-agent-book.md","lastUpdated":1786803890000}'),n={name:"tools/ai-agent-book.md"};function l(i,t,s,g,h,u){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-agent-book-拆解-《深入理解ai-agent-设计原理与工程实践》" tabindex="-1">ai-agent-book 拆解（《深入理解AI Agent：设计原理与工程实践》） <a class="header-anchor" href="#ai-agent-book-拆解-《深入理解ai-agent-设计原理与工程实践》" aria-label="Permalink to &quot;ai-agent-book 拆解（《深入理解AI Agent：设计原理与工程实践》）&quot;">​</a></h1><blockquote><p>来源：BV1EcGw6eE3o《深入理解AI Agent设计原理与工程实践（书评）》 | 拆解日期：2026-08-15 | 验证状态：✅已确认 GitHub：<a href="https://github.com/bojieli/ai-agent-book" target="_blank" rel="noreferrer">https://github.com/bojieli/ai-agent-book</a> | 作者：李博杰（Pine AI 首席科学家） | 许可证：Apache License 2.0</p></blockquote><h2 id="一句话概括" tabindex="-1">一句话概括 <a class="header-anchor" href="#一句话概括" aria-label="Permalink to &quot;一句话概括&quot;">​</a></h2><p>一本<strong>把 AI Agent 从概念讲到生产级工程</strong>的开源教材：10 章正文 + 60+ 个可直接运行的实验代码，核心就一句话——<code>Agent = LLM + 上下文 + 工具</code>（扩展为 <code>+ 约束 + 验证 + 纠正</code>）。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><ul><li>市面上的 Agent 内容两极分化：科普类画圈圈讲 ReAct，看完不会写一行代码；玩具类&quot;三行代码 LangChain 做个 Agent&quot;，跑不了生产。</li><li>从业者真正缺的是<strong>从第一性原理出发、系统且工程化</strong>的 Agent 知识，尤其是&quot;可靠地跑起来&quot;（harness）而不是&quot;能跑起来&quot;。</li><li>对用户的具体价值：不需要追三天过时的热点，按章节读、按 demo 跑，就能建立稳定的 Agent 知识框架。</li></ul><h2 id="产品-技术怎么设计的" tabindex="-1">产品/技术怎么设计的 <a class="header-anchor" href="#产品-技术怎么设计的" aria-label="Permalink to &quot;产品/技术怎么设计的&quot;">​</a></h2><ul><li><strong>核心公式即全书骨架</strong>：<code>Agent = LLM + 上下文 + 工具</code>（大脑 + 眼睛 + 手脚）。三个部件对应三种失效原因：模型不行 → 换模型；上下文不足 → 补上下文；工具不够 → 加工具——<strong>先诊断再优化</strong>。</li><li><strong>扩展公式（真正的竞争力）</strong>：<code>Agent = LLM + 上下文 + 工具 + 约束 + 验证 + 纠正</code>，即 model + harness。约束限定能做什么不能做什么，验证检查做得对不对，纠正出错后补正。</li><li><strong>每章配可运行代码</strong>：10 章正文 + 60+ demo，全仓库可 clone 直接跑；用对比思维、实验说话。</li><li><strong>关键技术议题</strong>（书中内容，视频转述）： <ul><li>上下文工程：KV cache 三条定律——系统提示词与工具定义定稿后不要改（多一个空格缓存全废）；动态信息永远追加到对话末尾；用标准 API 格式，不手拼字符串。</li><li>诊断方法：<strong>模型替换</strong>（固定 harness 换模型）与<strong>消融</strong>（固定模型关 harness 组件）是两回事，分别定位&quot;模型瓶颈&quot;和&quot;harness 瓶颈&quot;。</li><li>LLM-as-Judge 的坑：长度偏差（评委偏好更长回答）、Goodhart 定律（指标变目标就不再是好指标）；对策是多元异构评委（agent 用 Claude、评委用 GPT+Gemini，偏见正交）。</li><li>后训练：SFT 记忆（学固定映射）vs RL 泛化（学策略）；顺序不能反——&quot;SFT 立行，RL 求神&quot;；数据与环境比算法重要，仿真保真度决定决策能不能上线。</li></ul></li><li><strong>对 Claude Code 的判断</strong>：它的 harness 里绝大多数代码不是工具本身（文件读写/命令执行/检索只占小部分），核心是围绕工具的保障机制——流程状态管理、多层上下文压缩、权限分类、熔断器、错误恢复。视频据此断言：<strong>各家模型能力趋同后，竞争优势转移到模型之外的工程实践</strong>（从&quot;能做事&quot;到&quot;可靠地做事&quot;）。</li></ul><h2 id="最有创意的点" tabindex="-1">最有创意的点 <a class="header-anchor" href="#最有创意的点" aria-label="Permalink to &quot;最有创意的点&quot;">​</a></h2><p><strong>把&quot;模型能力趋同 → 竞争在 harness&quot;这个判断，落成一个可执行的诊断公式。</strong> 不是空喊&quot;工程化很重要&quot;，而是给你一个三栏定位法：表现不好时先判断是大脑（模型）、眼睛（上下文）还是手脚（工具），再决定换模型、补上下文还是加工具——<strong>先诊断后投入，避免无效优化</strong>（视频作者自己就踩过&quot;花时间做了无效优化&quot;的坑）。加上&quot;模型最终会一层层吃掉 harness、但 harness 不会消失&quot;的终局判断，让读者知道该把力气长期投在哪里。</p><h2 id="能解决什么落地问题" tabindex="-1">能解决什么落地问题 <a class="header-anchor" href="#能解决什么落地问题" aria-label="Permalink to &quot;能解决什么落地问题&quot;">​</a></h2><ul><li><strong>诊断自己的 Agent 流水线</strong>：「工具情报官」这类 agent 系统遇到表现不佳时，按公式定位是上下文不够还是工具不够，而不是盲目换模型/加积分。</li><li><strong>学习 harness 设计</strong>：约束/验证/纠正三件套可以直接照搬到自研工具（如转录失败降级、验证状态标注、报告模板约束）——本流水线的 skill 已经采用。</li><li><strong>直接可跑的 60+ 实验</strong>：想深入 agent 工程细节时，按章 clone 仓库跑 demo，比看视频效率更高、信息更密。</li><li><strong>成本判断</strong>：很多场景 SFT 数据质量到位就不需要 RL（RL 贵 10-100 倍且不稳定）——对想训模型的团队是省钱指南。</li></ul><h2 id="可借鉴到我自己工具的地方" tabindex="-1">可借鉴到我自己工具的地方 <a class="header-anchor" href="#可借鉴到我自己工具的地方" aria-label="Permalink to &quot;可借鉴到我自己工具的地方&quot;">​</a></h2><ol><li><strong>流水线公式化</strong>：把「工具情报官」也写成显式公式（采集+总结+验证+拆解+沉淀），任何一步出问题按公式定位，而不是整体返工。</li><li><strong>KV cache 三条定律 → 系统提示词管理</strong>：persona/skill 内容一旦定稿不要频繁改；动态信息（日期、队列状态）追加到末尾——本 skill 已按此设计。</li><li><strong>模型替换 vs 消融</strong>：评估流水线质量时，固定流程换模型、固定模型关组件，分别看瓶颈。</li><li><strong>多元异构验证</strong>：工具验证不只听一个来源（视频说的不算，官网+GitHub+搜索交叉确认）——skill 的验证状态机制就是它的落地。</li><li><strong>约束-验证-纠正</strong>：报告生成加约束（模板字段齐全才算完成）、验证（来源可查）、纠正（缺素材/失败降级不阻塞）。</li></ol><hr><p><em>来源依据：BV1EcGw6eE3o 转录全文 + <a href="https://github.com/bojieli/ai-agent-book" target="_blank" rel="noreferrer">GitHub 仓库</a> + <a href="https://zhuanlan.zhihu.com/p/2065218525564777811" target="_blank" rel="noreferrer">知乎书评</a> + <a href="https://www.cnblogs.com/itech/p/21701795" target="_blank" rel="noreferrer">博客园介绍</a> + <a href="https://x.com/bojie_li/status/2079092072305590280" target="_blank" rel="noreferrer">X 作者动态</a>。Claude Code harness 佐证：<a href="https://zhuanlan.zhihu.com/p/2022795894202925545" target="_blank" rel="noreferrer">知乎·看看Claude Code怎么做Harness</a>。</em></p>',16)])])}const b=e(n,[["render",l]]);export{d as __pageData,b as default};
